CREATE FUNCTION public.q57_fetched_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.mapping_id IS DISTINCT FROM OLD.mapping_id OR NEW.client_pipeline_id IS DISTINCT FROM OLD.client_pipeline_id OR NEW.month IS DISTINCT FROM OLD.month OR NEW.source IS DISTINCT FROM OLD.source OR NEW.fetched_values IS DISTINCT FROM OLD.fetched_values OR NEW.fetched_at IS DISTINCT FROM OLD.fetched_at OR NEW.raw_data IS DISTINCT FROM OLD.raw_data THEN RAISE EXCEPTION 'Fetched source provenance is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER q57_fetched_identity_guard BEFORE UPDATE ON public.kpi_fetched_values FOR EACH ROW EXECUTE FUNCTION public.q57_fetched_identity_guard();
CREATE FUNCTION public.scorecard_band(_score numeric) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _score IS NULL THEN NULL WHEN _score>=coalesce((SELECT (value->>'green')::numeric FROM app_settings WHERE key='scorecard_bands'),90) THEN 'green' WHEN _score>=coalesce((SELECT (value->>'amber')::numeric FROM app_settings WHERE key='scorecard_bands'),70) THEN 'amber' ELSE 'red' END $$;
CREATE FUNCTION public.set_scorecard_bands(_green numeric,_amber numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF _green>100 OR _green<=_amber OR _amber<0 THEN RAISE EXCEPTION 'Use 0 ≤ Amber < Green ≤ 100'; END IF; INSERT INTO app_settings(key,value) VALUES('scorecard_bands',jsonb_build_object('green',_green,'amber',_amber)) ON CONFLICT(key) DO UPDATE SET value=excluded.value; END $$;
REVOKE ALL ON FUNCTION public.set_scorecard_bands(numeric,numeric) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_scorecard_bands(numeric,numeric) TO authenticated;
